    private static long termHash(Value v) {
        if (v == null) return 0;
        long h = 31L * v.stringValue().hashCode() + (v.isIRI() ? 1 : v.isBNode() ? 2 : 3);
        if (v instanceof org.eclipse.rdf4j.model.Literal l) {
            h = 31*h + l.getDatatype().stringValue().hashCode();
            h = 31*h + l.getLanguage().orElse("").hashCode();
        }
        return h;
    }

	static long load(SailRepository repository, int groups, int fanout) {
		long triples = 0;
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			connection.begin();
			for (int group = 0; group < groups; group++) {
				IRI subject = vf.createIRI(NS, "group/" + group);
				connection.add(subject, vf.createIRI(NS, "type"), vf.createIRI(NS, "Group"));
				connection.add(subject, vf.createIRI(NS, "label"), vf.createLiteral("Group label " + group));
				connection.add(subject, vf.createIRI(NS, "seed"), vf.createLiteral("Seed " + group));
				triples += 3;
				for (int arm = 0; arm < 3; arm++) {
					for (int member = 0; member < fanout; member++) {
						IRI node = vf.createIRI(NS, "node/" + group + "/" + arm + "/" + member);
						connection.add(subject, vf.createIRI(NS, "arm" + arm), node);
						triples++;
						for (int col = 0; col < 8; col++) {
							if (col == 7 && member % 7 == 0) {
								continue; // Nested OPTIONAL's entire four-column suffix becomes unbound.
							}
							connection.add(node, vf.createIRI(NS, "a" + col), vf.createLiteral(
									"Shared lexical prefix é 漢字 " + group + "/" + arm + "/" + member + "/" + col,
									"nb"));
							triples++;
						}
					}
				}
			}
			connection.commit();
		}
		return triples;
	}

	private static String query() {
		StringBuilder select = new StringBuilder("SELECT DISTINCT ?s ?label ?seed ");
		StringBuilder body = new StringBuilder(" WHERE { ?s <" + NS + "type> <" + NS + "Group> ; <"
				+ NS + "label> ?label ; <" + NS + "seed> ?seed . ");
		for (int arm = 0; arm < 3; arm++) {
			select.append("?n").append(arm).append(' ');
			body.append(" OPTIONAL { ?s <")
					.append(NS)
					.append("arm")
					.append(arm)
					.append("> ?n")
					.append(arm)
					.append(" . OPTIONAL { ");
			for (int col = 0; col < 8; col++) {
				if (System.getProperty("audit.shape", "narrow").equals("wide"))
                    select.append("?v").append(arm).append('_').append(col).append(' ');
				if (col == 4) {
					body.append(" OPTIONAL { ");
				}
				body.append("?n")
						.append(arm)
						.append(" <")
						.append(NS)
						.append('a')
						.append(col)
						.append("> ?v")
						.append(arm)
						.append('_')
						.append(col)
						.append(" . ");
			}
			body.append(" } } } ");
		}
		return select.append(body).append('}').toString();
	}
